import java.util.Scanner;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        int[] sorted = {a, b};
        if (a > b) {
            int temp = sorted[0];
            sorted[0] = sorted[1];
            sorted[1] = temp;
        }
        int x = sorted[0];
        int y = sorted[1];

        Map<Integer, Integer> specialValues = Map.of(
            1, Math.min(y % 6, 6 - y % 6),
            2, 2 * (y == 3 || y == 7 ? 1 : 0) + 4 * (y == 2 ? 1 : 0)
        );

        int value;
        if (specialValues.containsKey(x)) {
            value = x * y - specialValues.get(x);
        } else {
            value = x & 1 * y & 1;
        }

        System.out.println(value);
        scanner.close();
    }
}
